"""Bind manually opened final views and verified FBX/fixture checks to the handoff."""
import json,hashlib,struct,re
from pathlib import Path
R=Path(__file__).resolve().parents[3];O=R/'Art/Models/GutKit'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
build=json.loads((O/'metrics/build.json').read_text())
for e,v in build['sha256'].items():assert sha(O/('GutKit.'+e))==v
for n in ['roundtrip','fbx-axes','fixture-audit']:assert json.loads((O/f'metrics/{n}.json').read_text())['result']=='PASS'
rows=[]
for p in sorted((O/'renders').rglob('*.png')):
 size=struct.unpack('>II',p.read_bytes()[16:24]);rows.append({'file':p.relative_to(O).as_posix(),'sha256':sha(p),'size':size,'opened_individually':True})
assert len(rows)==37,len(rows)
(O/'visual-review.json').write_text(json.dumps({'reviewer':'Codex 2 (WSL CLI)','scope':'Artist geometry, material, camera and action review only; no native Unity acceptance. Each listed image individually opened through view_image.','images':rows},indent=2)+'\n')
lines=['# GUT-ART-1 — close-up gutting kit','','Codex 2 (WSL CLI), 2026-10-25. Artist delivery complete; Unity import, Legacy clip setup and gameplay acceptance belong to Claude. Studio and assembly frames are isolated Blender evidence.','','[Editable kit](GutKit.blend) · [FBX](GutKit.fbx) · [Camera fixture](GutKit-camera-fixture.blend)','','## Items and budgets','','All six named items share zero origins intentionally. Hide unused children before displaying one; clean source/export overlaps them for modular instantiation. Sizes below use Unity local **X × Y × Z**, metres.','','| Item | Tris / limit | Overall bounds, m | Pivot / use |','|---|---:|---|---|']
notes={'GutBoard':'Worktop centre Y=0; 0.70 × 0.36 substrate extends down 42mm; 4mm edge groove; steel clamp at +X rises to59.3mm. Place fish on Y=0, head toward +X.','GutKnife':'Blade tip at0; handle extends -X, blade lies in XZ plane. Translate tip along cut; rotate local +Y to aim -X handle behind tip.','BellyOpen':'Vent at X=0 to gills X=1, faces +Y. Multiply X scale by cut length in metres; Z sets width. Thin4–12mm raised flesh/cavity.','BellyRagged':'Same pivot/length as BellyOpen, alternating torn outer lip. Toggle clean versus ragged explicitly.','GutBucket':'Base centre Y=0; open top +Y; steel bucket with folded handle and3 dark offal lumps.','GullSkin':'Instantiate GullPerch subtree. Between feet Y=0, faces +Z; folded wings. Four-bone GullRig drives GullSkin.'}
for n,v in build['meshes'].items():
 dims=[b-a for a,b in zip(*v['bounds_unity'])];label='GullPerch (GullSkin)' if n=='GullSkin' else n
 lines.append('| '+label+' | '+str(v['triangles'])+' / '+str(build['limits'][n])+' | '+' × '.join(f'{x:.4f}' for x in dims)+' | '+notes[n]+' |')
lines+=['','Total **1,397 triangles**. No textures, external images, cameras, lights, fish or table in the clean source/export. The six items are named direct children of GutKit; GullPerch contains GullRig → GullSkin.','','## Axes, materials and actions','','Blender authoring is Z-up. Unity coordinates are `(Blender X, Blender Z, -Blender Y)`. FBX declares Y-up, UnitScaleFactor100cm per geometric unit, with the standard root conversion retained for the animated rig. World geometry/zero pivots verified directly from raw FBX transforms and fresh FBX reimport; do not rotate another90 degrees or compensate with scale100. Configure Unity Model scale1 and Animation Type Legacy, matching Seal. No Unity import settings are authored here.','','Materials use only the permitted names; map by slot name to shared game materials. Matte steel matches the existing GuttingTable palette.','','| Slot | sRGB |','|---|---|']
for k,v in build['palette'].items():lines.append(f'| {k} | {v} |')
lines+=['','Gull actions: **Idle**, frames1–121 at30fps (4s), loop; **Lunge**, frames1–31 (1s), one-shot returning to perch. Exported FBX take names carry the armature prefix (`GullRig|Idle`, `GullRig|Lunge`); expose them as Idle/Lunge when importing. Idle breathes and looks; Lunge tips body/neck/head toward +Z while feet stay fixed. Lunge max sampled vertex travel0.278m; no root translation. Four bones Root/Body/Neck/Head; weights sum1. FBX baked every frame; import Legacy, loop Idle only.','','## Opened evidence','','Five1000×800 orthographic studio views per item, front toward Unity -Z, right from +X. Thin inserts are deliberately edge-on in front/back.','','| Item | Three-quarter | Front | Right | Back | Top |','|---|---|---|---|---|---|']
for n in ['GutBoard','GutKnife','BellyOpen','BellyRagged','GutBucket','GullPerch']:
 lines.append('| '+n+' | '+' | '.join(f'[{v}](renders/{n}/{v}.png)' for v in ['three-quarter','front','right','back','top'])+' |')
lines+=['','Lunge sampled frames: '+', '.join(f'[{f}](renders/action/Lunge-{f:02d}.png)' for f in [1,8,16,23,31])+'.','','Assembly: [1440×900](renders/assembly/gut-view-1440.png), [844×390](renders/assembly/gut-view-844.png). Camera0.9m above board,60° down,55° horizontal FOV retained at both aspect ratios. Existing GuttingTable appended read-only; canonical Fish043 Mackerel laid on its side at1.5× (~0.51m), fitted0.25m BellyOpen cut; knife, bucket and gull complete the context. Fixture placements are in [assembly.json](assembly.json). Fish meshes stay canonical and uncut: insert is an overlay and runtime should hide/interpolate it as appropriate.','','## Checks and reproduction','','[Actual FBX geometry/material/animation audit](metrics/roundtrip.json), [raw axes and units](metrics/fbx-axes.json), [independent camera/framing/protected-reference check](metrics/fixture-audit.json), [build bounds](metrics/build.json), [reference hashes](metrics/references.json), [individual image receipt](visual-review.json), [delivery inventory](delivery-receipt.json). Every exported rest mesh and ten sampled deformed poses match source within20µm; hierarchy/materials/weights/triangle budgets pass. Every final image was individually opened. Native HUD and actual Legacy playback remain untested.','','From project root: `python3 Art/Source/GutKit/run.py build audit axes render fixture_audit`. Installed Windows Blender5.2 is launched sequentially with explicit completion markers. Rebuilds require fresh image review and finalization. [Builder](../../Source/GutKit/build.py), [FBX audit](../../Source/GutKit/audit.py), [renderer](../../Source/GutKit/render.py), [fixture audit](../../Source/GutKit/fixture_audit.py), [finalizer](../../Source/GutKit/finalize.py).','','Read-only SortingBoard, GuttingTable, canonical Mackerel and Seal hashes remain unchanged. No Unity/Assets/runtime/save/git changes or native acceptance claimed.']
(O/'REPORT.md').write_text('\n'.join(lines)+'\n')
for dest in re.findall(r'\]\(([^)]+)\)',(O/'REPORT.md').read_text()):
 if dest!='delivery-receipt.json':assert (O/dest).is_file(),dest
files=[p for d in [O,R/'Art/Source/GutKit'] for p in d.rglob('*') if p.is_file() and p.name!='delivery-receipt.json' and '__pycache__' not in str(p) and '.backup' not in str(p)]
receipt={'task':'GUT-ART-1','owner':'Codex 2 (WSL CLI)','status':'artist complete; native acceptance external','files':[{'file':p.relative_to(R).as_posix(),'bytes':p.stat().st_size,'sha256':sha(p)} for p in sorted(files)]}
(O/'delivery-receipt.json').write_text(json.dumps(receipt,indent=2)+'\n');print('GUT FINAL',len(files),'files',len(rows),'opened images')
